#{item}
AND bo.BID_ID LIKE CONCAT('%',CONCAT(#{bidId},'%'))
union all SELECT '01' AS validStatus/*有效状态*/, CASE WHEN brt.IS_WIN = 'Y' THEN '04' WHEN brt.IS_WIN = 'N' THEN '03' WHEN brt.TOTAL_WIN_ID IS NULL THEN '02' END AS firstBidStatus/*中标状态*/, bo.BID_ID AS bidId/*投标编号*/, fp.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId/*资产代码*/, fp.FINPROD_ABBR finprodAbbr/*资产简称*/, fpi.TENDER_TARGET tenderTarget/*招标标的*/, CASE WHEN fpi.ISSUE_CLASS = '02' AND fpi.TENDER_TYPE IN ('01', '02') THEN fpi.ISSUE_DATE WHEN (fpi.ISSUE_CLASS = '02' AND (fpi.TENDER_TYPE IS NULL OR fpi.TENDER_TYPE IN ('03', '04'))) OR fpi.ISSUE_CLASS = '03' THEN fpi.TENDER_SDATE END AS bidDateStart/*投标日 开始*/, CASE WHEN fpi.ISSUE_CLASS = '02' AND fpi.TENDER_TYPE IN ('01', '02') THEN fpi.ISSUE_DATE WHEN (fpi.ISSUE_CLASS = '02' AND (fpi.TENDER_TYPE IS NULL OR fpi.TENDER_TYPE IN ('03', '04'))) OR fpi.ISSUE_CLASS = '03' THEN fpi.TENDER_SDATE END AS bidDateEnd/*投标日 结束*/, ee.ENTRUST_NUM AS etrBidPriceTotal/*指令投标券面总额*/, bo.WIN_PRIN_AMT AS bidPriceTotal/*券面总额*/, bobp.BID_PRICE AS bidprice/*投标标位, 多个逗号分隔展示*/, bo.BID_MODLE AS biddingMethod/*投标方式*/, bo.PAY_TYPE AS payType/*缴款方式*/, case when fpi.TENDER_TARGET = '01' then to_char(bo.WIN_PRICE * 100, 'FM99990.9990') || '%' when fpi.TENDER_TARGET = '02' then to_char(bo.WIN_PRICE, 'FM99990.9990') || '元' when fpi.TENDER_TARGET = '03' then to_char(bo.WIN_PRICE * 10000, 'FM99990.90') || 'BP' end winPrice/*中标标位*/, bo.UNIT_CPRICE price/*净价*/, bo.PAYABLE_AMOUNT payableAmount/*缴款金额*/, bo.SETT_FEE_AMT settFeeAmt/*结算服务费*/, bo.PAY_DATE payDate/*缴款日*/, bo.ASSIGN_REGDATE assignRegdate/*债权债务登记日*/, bo.ONMARKET_DATE listingDate/*上市日*/, bo.BID_DATE AS bidDate/*投标确认日*/, bo.COUNTER_ID counterId/*交易对手*/, mci.CUSTOMER_NAME AS counterName/*交易对手*/, bo.REMARK AS remark/*备注*/, fp.TRADE_MARKET tradeMarket/*交易场所*/, null dealDate/*成交日期*/ FROM WFL_BID_ORDER bo LEFT JOIN (select listagg(case when t3.TENDER_TARGET = '01' then to_char(t0.BID_PRICE * 100, 'FM99990.9990') || '%' when t3.TENDER_TARGET = '02' then to_char(t0.BID_PRICE, 'FM99990.9990') || '元' when t3.TENDER_TARGET = '03' then to_char(t0.BID_PRICE * 10000, 'FM99990.90') || 'BP' end, ',') within group (order by t0.ENTRUST_ID) AS BID_PRICE, t0.BID_ID from WFL_BID_ORDER_BID_PRICE t0 LEFT JOIN WFL_BID_ORDER t1 on t1.BID_ID = t0.BID_ID LEFT JOIN FIN_PRODUCT t2 ON t2.FINPROD_ID = t1.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE t3 ON t3.FINPROD_ID = t2.FINPROD_ID group by t0.BID_ID) bobp ON bobp.BID_ID = bo.BID_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = bo.FINPROD_ID LEFT JOIN (select distinct ENTRUST_ID, BID_ID from WFL_BID_ORDER_BID_PRICE) bobp1 ON bobp1.BID_ID = bo.BID_ID LEFT JOIN FIN_PRODUCT_ISSUE fpi ON fpi.FINPROD_ID = fp.FINPROD_ID LEFT JOIN BID_RESULT_TOTAL brt ON brt.FINPROD_ID = fp.FINPROD_ID AND brt.BID_ID = bo.BID_ID LEFT JOIN ETR_ENTRUST ee ON ee.ENTRUST_ID = bobp1.ENTRUST_ID LEFT JOIN MST_CUSTOMER_INFO mci ON mci.CUSTOMER_ID = bo.COUNTER_ID WHERE bo.BID_MODLE IN ('03')
AND
#{item}
AND
#{item}
AND
#{item}
AND
#{item}
AND
#{item}
AND bo.BID_ID LIKE CONCAT('%',CONCAT(#{bidId},'%'))
) T left join SYS_DATADICT_LIST sdl_sv on T.validStatus=sdl_sv.ITEM_CODE and sdl_sv.DICT_CODE='STATUS_VALID' left join SYS_DATADICT_LIST sdl_fbs on T.firstBidStatus=sdl_fbs.ITEM_CODE and sdl_fbs.DICT_CODE='FIRST_BID_STATUS' left join SYS_DATADICT_LIST sdl_tt on T.tenderTarget=sdl_tt.ITEM_CODE and sdl_tt.DICT_CODE='TENDER_TARGET' left join SYS_DATADICT_LIST sdl_wt on T.biddingMethod=sdl_wt.ITEM_CODE and sdl_wt.DICT_CODE='WIN_TYPE' left join SYS_DATADICT_LIST sdl_ept on T.payType=sdl_ept.ITEM_CODE and sdl_ept.DICT_CODE='ETR_PAY_TYPE' left join SYS_DATADICT_LIST sdl_tp on T.tradeMarket=sdl_tp.ITEM_CODE and sdl_tp.DICT_CODE='TRADE_PLACE'
AND
#{item}
AND T.bidDateStart = #{bidDateStart}
AND T.bidDateEnd = #{bidDateEnd}
AND
#{item}
group by T.validStatus, T.firstBidStatus, T.bidId, T.finprodId, T.finprodMarketId, T.finprodAbbr, T.bidDateStart, T.bidDateEnd, T.bidPriceTotal, T.bidprice, T.biddingMethod, T.payType, T.winPrice, T.price, T.payableAmount, T.settFeeAmt, T.payDate, T.assignRegdate, T.listingDate, T.bidDate, T.counterName,T.remark, T.dealDate,T.tradeMarket,T.tenderTarget,T.counterId

sql.if:
( T.validStatus || '|' || sdl_sv.item_value || '|' || T.firstBidStatus || '|' || sdl_fbs.item_value
|| '|' || T.tenderTarget || '|' || sdl_tt.item_value || '|' || T.biddingMethod || '|' || sdl_wt.item_value
|| '|' || T.payType || '|' || sdl_ept.item_value || '|' || T.tradeMarket || '|' || sdl_tp.item_value
|| '|' || T.bidId  || '|' || T.finprodId || '|' || T.finprodMarketId || '|'
|| '|' || T.finprodAbbr || '|' || T.counterId || '|' || T.counterName || '|' || T.remark
like '%' || #{search} || '%'
or decode(T.etrBidPriceTotal,0,'0.00',to_char(T.etrBidPriceTotal/10000,'FM99999999999990.90'))=#{search} or to_char(T.etrBidPriceTotal)=#{search}
or decode(T.bidPriceTotal,0,'0.00',to_char(T.bidPriceTotal/10000,'FM9999999999990.90'))=#{search} or to_char(T.bidPriceTotal)=#{search}
or decode(T.bidprice,0,'0.00',to_char(T.bidprice,'FM999999999990.9990'))=#{search} or to_char(T.bidprice)=#{search}
or replace(to_char(T.bidDateStart,'yyyy-MM-dd'),'-','/')=#{search}
or replace(to_char(T.bidDateEnd,'yyyy-MM-dd'),'-','/')=#{search}
or replace(to_char(T.bidDate,'yyyy-MM-dd'),'-','/')=#{search}
)

